/** One note icon, decorative; a drop when the icon is unknown. */
function frave_note_icon( string $icon ): string {
	$shapes = frave_note_icon_shapes();
	$shape  = $shapes[ $icon ] ?? '<path d="M12 3c3 4 6 7 6 11a6 6 0 0 1-12 0c0-4 3-7 6-11z"/>';
	return '<svg class="note-icon" viewBox="0 0 24 24" aria-hidden="true" focusable="false">' . $shape . '</svg>';
}
